from typing import TypedDict, NotRequired, Required
from typing_extensions import TypedDict as ExtTypedDict, NotRequired as ExtNotRequired, Required as ExtRequired
from cattrs import Converter
import pytest

def test_mixed_required_notrequired():
    class Mixed(TypedDict):
        a: Required[int]
        b: NotRequired[int]
        c: int

    c = Converter()
    # Valid: a and c are required, b is optional
    data = {"a": 1, "c": 3}
    structured = c.structure(data, Mixed)
    assert structured == data

    data_with_b = {"a": 1, "b": 2, "c": 3}
    structured_with_b = c.structure(data_with_b, Mixed)
    assert structured_with_b == data_with_b

    # Invalid: a is missing
    with pytest.raises(Exception):
        c.structure({"c": 3}, Mixed)

def test_nested_typeddicts():
    class Inner(TypedDict):
        x: int

    class Outer(TypedDict):
        inner: Inner
        y: int

    c = Converter()
    data = {"inner": {"x": 1}, "y": 2}
    structured = c.structure(data, Outer)
    assert structured == data

def test_typeddict_inheritance():
    class Base(TypedDict):
        a: int

    class Derived(Base):
        b: int

    c = Converter()
    data = {"a": 1, "b": 2}
    structured = c.structure(data, Derived)
    assert structured == data

def test_extensions_typeddict():
    class ExtMixed(ExtTypedDict):
        a: ExtRequired[int]
        b: ExtNotRequired[int]

    c = Converter()
    data = {"a": 1}
    structured = c.structure(data, ExtMixed)
    assert structured == data

def test_complex_inheritance():
    class A(TypedDict):
        a: int
    class B(TypedDict):
        b: int
    class C(A, B):
        c: int

    c = Converter()
    data = {"a": 1, "b": 2, "c": 3}
    structured = c.structure(data, C)
    assert structured == data
